var a=`0631-taameya`;var n=`world-0631`;var r=`EG`;var t=`northern-africa`;var s=4;var o=545;var l={en:`Ta'ameya`,ua:`Таамея`};var d={en:`Ta'ameya is a Egypt classic prepared with fava beans, yellow onion, garlic, parsley. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Таамея, страва кухні країни Єгипет зі складниками: боби фава, жовта цибуля, часник, петрушка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`fava-beans`,350,`g`],[`water`,850,`ml`]]},{en:`Drain and peel soaked fava beans where possible; grind with herbs and spices into a coarse paste, not a watery puree.`,ua:`Злийте воду із замочених бобів, за можливості очистьте шкірку; подрібніть із зеленню та спеціями до густої грубої пасти.`,t:[`mixing`],m:12,i:[[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`parsley`,25,`g`],[`cilantro`,25,`g`],[`ground-cumin`,7,`g`],[`ground-coriander`,6,`g`],[`baking-soda`,3,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 30 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 30 хвилин.`,t:[`rapid-chilling`],m:30,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 20 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 20 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:20,i:[[`sunflower-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`tahini`,90,`g`],[`lemon-juice`,30,`ml`]]}];var u={slug:a,id:n,country:`EG`,region:t,servings:4,minutes:545,title:l,text:d,steps:g};export{r as country,u as default,n as id,o as minutes,t as region,s as servings,a as slug,g as steps,d as text,l as title};